package com.brokerdealer.executionservice.config;

import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpRequest;
import org.springframework.http.client.ClientHttpRequestExecution;
import org.springframework.http.client.ClientHttpRequestInterceptor;
import org.springframework.http.client.ClientHttpResponse;
import org.springframework.stereotype.Component;

import java.io.IOException;

/**
 * Adds the service-to-service token and SYSTEM role headers to outbound calls
 * made to marketdata-service by the LIMIT order price monitor (SCRUM-48).
 * Requests to any other host are passed through unchanged.
 */
@Component
@Slf4j
public class ServiceTokenInterceptor implements ClientHttpRequestInterceptor {

    private static final String ROLE_HEADER = "X-User-Role";
    private static final String SYSTEM_ROLE = "SYSTEM";

    private final String serviceToken;
    private final String tokenHeader;
    private final String marketDataBaseUrl;

    public ServiceTokenInterceptor(@Value("${app.marketdata.service-token}") String serviceToken,
                                   @Value("${app.marketdata.token-header:X-Service-Token}") String tokenHeader,
                                   @Value("${app.marketdata.base-url:http://localhost:8084}") String marketDataBaseUrl) {
        this.serviceToken = serviceToken;
        this.tokenHeader = tokenHeader;
        this.marketDataBaseUrl = marketDataBaseUrl;
    }

    @Override
    public ClientHttpResponse intercept(HttpRequest request, byte[] body,
                                        ClientHttpRequestExecution execution) throws IOException {
        if (request.getURI().toString().startsWith(marketDataBaseUrl)) {
            request.getHeaders().set(tokenHeader, serviceToken);
            request.getHeaders().set(ROLE_HEADER, SYSTEM_ROLE);
            log.debug("Service token attached: host={} path={}",
                    request.getURI().getHost(), request.getURI().getPath());
        }
        return execution.execute(request, body);
    }
}

