 * rejected before anything is persisted or published.
 */
private static final Map<OrderStatus, Set<OrderStatus>> ALLOWED_TRANSITIONS = new EnumMap<>(OrderStatus.class);

static {
    ALLOWED_TRANSITIONS.put(OrderStatus.NEW,
            EnumSet.of(OrderStatus.VALIDATED, OrderStatus.REJECTED));
    ALLOWED_TRANSITIONS.put(OrderStatus.VALIDATED,
            EnumSet.of(OrderStatus.RISK_CHECK_PASSED, OrderStatus.RISK_REJECTED));
    ALLOWED_TRANSITIONS.put(OrderStatus.RISK_CHECK_PASSED,
            EnumSet.of(OrderStatus.ACCEPTED));
    ALLOWED_TRANSITIONS.put(OrderStatus.ACCEPTED,
            EnumSet.of(OrderStatus.SENT_TO_EXECUTION));
    ALLOWED_TRANSITIONS.put(OrderStatus.SENT_TO_EXECUTION,
