import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;

import java.math.BigDecimal;

/**
 * REJECT orders whose notional value is below the configured minimum (USD).
 * Skipped when orderValue or threshold is not available.
 */
@RequiredArgsConstructor
@Slf4j
public class MinOrderValueRule implements RiskRule {

    private final BigDecimal threshold;
    private final boolean enabled;

    @Override
    public String getRuleCode() {
        return "RULE_MIN_ORDER_VALUE";
    }

    @Override
    public boolean isEnabled() {
        return enabled;
    }

    @Override
    public RiskResult evaluate(RiskEvaluationRequest request, RiskContext context) {
        if (request.getOrderValue() == null || threshold == null) {
            log.debug("RULE_MIN_ORDER_VALUE skipped: orderValue or threshold missing; orderId={}",
                    context.getOrderId());
            return RiskResult.passed();
        }
        BigDecimal orderValue = new BigDecimal(request.getOrderValue());
        if (orderValue.compareTo(threshold) < 0) {
            return RiskResult.rejected(getRuleCode(),
                    "Order value " + orderValue.toPlainString()
                            + " is below minimum allowed " + threshold.toPlainString() + " USD");
        }
        return RiskResult.passed();
    }
}

